async function getUserPreferences() {
  try {
    // Using no-store to ensure data is fetched on every request
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    });

    if (!res.ok) {
      throw new Error('Failed to fetch data');
    }

    return res.json();
  } catch (error) {
    // Fallback/mock data for demonstration
    return {
      username: 'johndoe',
      theme: 'dark',
      notificationsEnabled: true,
      lastActive: new Date().toISOString()
    };
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <div style={{ padding: '1rem', border: '1px solid #ccc', borderRadius: '4px' }}>
        <p><strong>Username:</strong> {preferences.username}</p>
        <p><strong>Theme:</strong> {preferences.theme}</p>
        <p><strong>Notifications:</strong> {preferences.notificationsEnabled ? 'Enabled' : 'Disabled'}</p>
        <p><strong>Last Active:</strong> {preferences.lastActive}</p>
      </div>
    </div>
  );
}

